#include <iostream>
#include <string>

int main() {
    std::string d = "dot";
    std::string input_str;
    std::getline(std::cin, input_str);
    std::string step1 = input_str;
    size_t pos = 0;
    while ((pos = step1.find(d)) != std::string::npos) {
        step1.replace(pos, d.length(), ".");
    }
    if (!step1.empty()) {
        step1[0] = (step1[0] == 'a') ? 'a' : step1[0]; // placeholder, no change needed here
    }
    if (!step1.empty() && step1[0] == '.') {
        step1 = d + step1.substr(1);
    }
    if (!step1.empty() && step1.back() == '.') {
        step1 = step1.substr(0, step1.size() - 1) + d;
    }
    size_t first_at = step1.find("at");
    if (first_at != std::string::npos) {
        step1.replace(first_at, 2, "@");
    }
    std::cout << step1 << std::endl;
    return 0;
}

